// Prototype rules, not trained probabilities. Laugh has its own score/threshold semantics.
export const classifierPolicy=Object.freeze({laughEnter:.65,laughExit:.45,mouthRange:[.25,.65],smileCoreExponent:1.2,eyeBonus:.1,openingJaw:[.15,.55],openingGeometry:[.08,.28],eyeRange:[.1,.5],maxSideWeight:.6})
const smooth=(x,a,b)=>{const t=Math.max(0,Math.min(1,(x-a)/(b-a)));return t*t*(3-2*t)}
export function laughEvidence(raw,context,config){const v=raw.values,p=context?.pose,valid=!p?.available||p.valid&&Math.abs(p.yaw)<=55&&Math.abs(p.pitch)<=40;if(!valid)return{score:0,reason:'unsupported pose',policy:classifierPolicy};const yaw=p?.valid?Math.abs(p.yaw):0,side=v.mouthSmileLeft>=v.mouthSmileRight?'Left':'Right',other=side==='Left'?'Right':'Left',weight=smooth(yaw,10,40)*classifierPolicy.maxSideWeight,mean=(v.mouthSmileLeft+v.mouthSmileRight)/2,mouth=mean*(1-weight)+v['mouthSmile'+side]*weight,eyeMean=(v.eyeSquintLeft+v.eyeSquintRight)/2,eye=eyeMean*(1-weight)+v['eyeSquint'+side]*weight,inhibition=1-smooth(Math.max(v.mouthFunnel,v.mouthPucker),.1,.35),smile=smooth(mouth,.25,.65)*smooth(v['mouthSmile'+other],.03,.18)*inhibition,jaw=smooth(v.jawOpen,.15,.55),geometry=Number.isFinite(context?.mouthOpenness)?smooth(context.mouthOpenness,.08,.28):null,opening=geometry===null?jaw:Math.min(1,.6*jaw+.4*geometry),support=smooth(eye,.1,.5),coreScore=Math.min(Math.pow(smile,classifierPolicy.smileCoreExponent),opening),supportBonus=.1*support*coreScore*(1-coreScore),openScore=Math.min(1,coreScore+supportBonus);
 // Existing well-supported closed grins remain compatible; high mouth alone is insufficient.
 const closedSupported=raw.smileIntensity>=config.laughEnter&&raw.eyeSquintScore>=.15,closedScore=.8*smooth(raw.smileIntensity,config.laughExit,config.laughEnter)*smooth(raw.eyeSquintScore,0,.15);
 return{score:Math.max(openScore,closedScore),smileEvidence:smile,openingEvidence:opening,eyeEvidence:support,otherSupportingEvidence:{eyeBonus:supportBonus,cheekRequired:false},coreScore,supportBonus,smileCoreEvidence:Math.pow(smile,classifierPolicy.smileCoreExponent),openingDisagreement:geometry===null?null:Math.abs(jaw-geometry),openingFusion:{jawWeight:geometry===null?1:.6,geometryWeight:geometry===null?0:.4,reliability:'not validated by pose-labeled paired samples'},p01GainAppliedToOpenLaugh:false,limitingFactor:Math.pow(smile,classifierPolicy.smileCoreExponent)<=opening?'smile-core':'mouth-opening',legacyThreeWayScore:Math.min(smile,opening,support),openScore,closedScore,rawMouth:mean,finalMouth:mouth,side,sideWeight:weight,jawEvidence:jaw,geometryEvidence:geometry,poseValid:valid,reason:'open laugh = minimum of smile and opening plus bounded optional eye bonus; P0-1 gain is not reapplied',policy:classifierPolicy}}
